// PreToolUse (Edit|Write): block hand edits of generated files.
import { readFileSync } from 'node:fs';
const f = (JSON.parse(readFileSync(0, 'utf8')).tool_input?.file_path || '').replaceAll('\\', '/');
const rules = [
  [/\/styles\/(brand|theme)\.css$/, 'Generated from tokens/: edit the JSON in tokens/ and run `pnpm tokens`.'],
  [/\/messages\/en\.d\.json\.ts$/, 'Generated by pnpm dev/build from messages/en.json: edit en.json instead.'],
];
for (const [re, why] of rules) if (re.test(f)) { process.stderr.write(why); process.exit(2); }
